# Generated by build.py from recipe.yml for recipe ftp-read-a-files-size-and-date. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'marker.txt'), "written after the time was set`n")
[IO.File]::WriteAllText((Join-Path $PWD 'keep-time.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Downloads the URL in the first argument with the curl options after it, then says`n# whether the local copy is older than marker.txt, a file written a moment ago.`nurl=`$1; shift`ncurl -s `"`$@`" -o copy.txt `"`$url`" || exit`nif [ copy.txt -ot marker.txt ]; then echo `"copy is older than marker.txt`"; else echo `"copy is new`"; fi`n")
cmd /c 'touch -t 202401021504.05 site/hello.txt'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--allow-anonymous', 'ftp://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -I ftp://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
